f32 hermite(f32* x, f32* v, f32 t)
{
    f32 t2 = t * t;
    f32 t3 = t * t2;
    f32 h01 = -(t3 + t3) + 3.0f * t2;
    f32 h11 = t3 - t2;
    f32 h10 = h11 - t2 + t;
    f32 h00 = -h01 + 1.0f;

    return x[0] * h00 + x[1] * h01 + v[0] * h10 + v[1] * h11;
}

void RotMatrix(Mtx m, Vec* vec)
{
    f32 sx;
    f32 sy;
    f32 sz;
    f32 cx;
    f32 cy;
    f32 cz;
    f32 szcx;
    f32 czsx;
    f32 szsx;
    f32 czcx;

    sx = sinf(vec->x);
    sy = sinf(vec->y);
    sz = sinf(vec->z);
    cx = cosf(vec->x);
    cy = cosf(vec->y);
    cz = cosf(vec->z);
    szcx = sz * cx;
    szsx = sz * sx;
    czsx = cz * sx;
    czcx = cz * cx;

    m[0][0] = cz * cy;
    m[0][1] = czsx * sy - szcx;
    m[0][2] = czcx * sy + szsx;
    m[0][3] = 0.0f;
    m[1][0] = sz * cy;
    m[1][1] = szsx * sy + czcx;
    m[1][2] = szcx * sy - czsx;
    m[1][3] = 0.0f;
    m[2][0] = -sy;
    m[2][1] = cy * sx;
    m[2][2] = cy * cx;
    m[2][3] = 0.0f;
}

void TransMatrix(Mtx m, Vec* pos)
{
    m[0][3] = pos->x;
    m[1][3] = pos->y;
    m[2][3] = pos->z;
}

void ScaleMatrix(Mtx m, Vec* vec)
{
    m[0][0] *= vec->x;
    m[0][1] *= vec->y;
    m[0][2] *= vec->z;
    m[1][0] *= vec->x;
    m[1][1] *= vec->y;
    m[1][2] *= vec->z;
    m[2][0] *= vec->x;
    m[2][1] *= vec->y;
    m[2][2] *= vec->z;
}

void VecRadLimit(f32* p)
{
    int i;

    for (i = 0; i < 3; i++) {
        while (p[i] >= PI) {
            p[i] -= PI2;
        }
        while (p[i] < -PI) {
            p[i] += PI2;
        }
    }
}

void SetOrientationZX(Vec* z, Vec* x, Mtx m)
{
    Vec vx;
    Vec vy;
    Vec vz;

    VECNormalize(x, &vx);
    VECNormalize(z, &vz);

    PSVECCrossProduct(&vz, &vx, &vy);
    VECNormalize(&vy, &vy);
    PSVECCrossProduct(&vy, &vz, &vx);
    VECNormalize(&vx, &vx);

    PSMTXIdentity(m);
    m[0][0] = vx.x;
    m[1][0] = vx.y;
    m[2][0] = vx.z;
    m[0][1] = vy.x;
    m[1][1] = vy.y;
    m[2][1] = vy.z;
    m[0][2] = vz.x;
    m[1][2] = vz.y;
    m[2][2] = vz.z;
}

void SetOrientationZY(Vec* z, Vec* y, Mtx m)
{
    Vec vx;
    Vec vy;
    Vec vz;

    VECNormalize(y, &vy);
    VECNormalize(z, &vz);

    PSVECCrossProduct(&vy, &vz, &vx);
    VECNormalize(&vx, &vx);
    PSVECCrossProduct(&vz, &vx, &vy);
    VECNormalize(&vy, &vy);

    PSMTXIdentity(m);
    m[0][0] = vx.x;
    m[1][0] = vx.y;
    m[2][0] = vx.z;
    m[0][1] = vy.x;
    m[1][1] = vy.y;
    m[2][1] = vy.z;
    m[0][2] = vz.x;
    m[1][2] = vz.y;
    m[2][2] = vz.z;
}

f32 VecAngle(Vec* vec_a, Vec* vec_b)
{
    f32 d = PSVECDotProduct(vec_a, vec_b);
    f32 l = PSVECMag(vec_a);

    l *= PSVECMag(vec_b);
    d /= l;
    return acosf(d < -1.0f ? -1.0f : (d > 1.0f ? 1.0f : d));
}

void VecLinearCombination(Vec* a, f32 c0, Vec* b, f32 c1, Vec* vec)
{
    Vec ta;
    Vec tb;

    PSVECScale(a, &ta, c0);
    PSVECScale(b, &tb, c1);
    PSVECAdd(&ta, &tb, vec);
}

